<script setup lang="ts">
const props=defineProps<{modelValue:any;schema:any;label?:string;path?:string;documentId?:string}>()
const emit=defineEmits<{'update:modelValue':[value:any]}>()
const picker=ref(false),title=computed(()=>props.schema.label||'內容項目'),hintId=useId(),errors=inject<any>('cms-field-errors',ref([]))
const fieldError=computed(()=>errors.value?.find((e:any)=>e.documentId===props.documentId&&e.path===(props.path||'').replace(/^\./,''))?.message)
const fields=computed(()=>Object.entries(props.schema.fields||{}).filter(([,s]:any)=>!Object.hasOwn(s,'fixed')&&!s.hidden) as [string,any][])
const asset=computed(()=>props.schema.format==='media'||['pdfUrl','brochureUrl','FRANCHISE_BROCHURE_URL'].includes(props.label||''))
const pdf=computed(()=>['pdfUrl','brochureUrl'].includes(props.label||'')||/PDF|型錄檔案/.test(title.value))
function set(key:string,value:any){emit('update:modelValue',{...props.modelValue,[key]:value})}
</script>
<template>
 <div class="cms-field-node" :data-cms-document="documentId" :data-cms-path="path">
 <AdminStoreRegions v-if="schema.editor==='store-regions'" :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" />
 <fieldset v-else-if="schema.type==='object'" class="cms-fields"><legend v-if="label">{{ title }}</legend><AdminHeroImages v-if="schema.editor==='hero-images'" :model-value="modelValue" :style="{'--hero-pan-x': Number(path?.split('.').at(-1)) % 2 === 1 ? '4%' : '-4%'}" @update:model-value="emit('update:modelValue',$event)" /><AdminStoreLocation v-if="schema.editor==='store-location'" :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" /><template v-for="[key,field] in fields" :key="key"><details v-if="key==='cmsSettings'||key==='seo'" class="cms-secondary"><summary>顯示與搜尋結果設定</summary><AdminFields :model-value="modelValue?.[key]" :schema="field" :document-id="documentId" :label="key" :path="`${path?path+'.':''}${key}`" @update:model-value="set(key,$event)" /></details><AdminFields v-else :model-value="modelValue?.[key]" :schema="field" :document-id="documentId" :label="key" :path="`${path?path+'.':''}${key}`" @update:model-value="set(key,$event)" /></template></fieldset>
 <AdminHomeCases v-else-if="schema.editor==='home-cases'" :model-value="modelValue" :label="title" :invalid="!!fieldError" @update:model-value="emit('update:modelValue',$event)" />
 <AdminItems v-else-if="schema.type==='array'" :model-value="modelValue||[]" :schema="schema" :document-id="documentId" :path="path" @update:model-value="emit('update:modelValue',$event)" />
 <div v-else-if="schema.enum" class="cms-field"><label :for="hintId+'-select'">{{ title }}</label><select :id="hintId+'-select'" :value="modelValue" :disabled="schema.readOnly" :aria-describedby="hintId" :aria-invalid="!!fieldError" @change="emit('update:modelValue',($event.target as HTMLSelectElement).value)"><option v-if="schema.optionLabels&&!schema.enum.includes(modelValue)" :value="modelValue">目前自訂尺寸（保留）</option><option v-for="(v,index) in schema.enum" :key="v" :value="v">{{ schema.optionLabels?.[index]||({latest:'最新消息',activities:'優惠活動',video:'影片'} as any)[v]||v }}</option></select></div>
 <div v-else-if="schema.type==='boolean'" class="cms-field"><label class="cms-checkbox"><input type="checkbox" :checked="modelValue" :aria-describedby="hintId" :aria-invalid="!!fieldError" @change="emit('update:modelValue',($event.target as HTMLInputElement).checked)" />{{ title }}</label></div>
 <label v-else-if="schema.type==='number'" class="cms-field">{{ title }}<input type="number" :value="modelValue" :aria-invalid="!!fieldError" :aria-describedby="hintId" @input="emit('update:modelValue',Number(($event.target as HTMLInputElement).value))" /></label>
 <div v-else-if="asset" class="cms-field"><strong>{{ title }}</strong><AdminImage v-if="modelValue&&!pdf" :src="modelValue" :alt="title" class="cms-field-thumbnail" :class="{'cms-field-thumbnail-dark':schema.previewTone==='dark'}" /><p v-else class="cms-field-help">{{ modelValue?'已選擇 PDF 檔案':'尚未選擇'+(pdf?'檔案':'圖片') }}</p><button type="button" class="cms-button" @click="picker=true">{{ modelValue?'更換':'選擇或上傳' }}{{ pdf?'檔案':'圖片' }}</button><AdminDialog :open="picker" :title="pdf?'選擇 PDF 檔案':'選擇圖片'" wide @close="picker=false"><AdminMediaGrid picking :kind="pdf?'pdf':'image'" @select="emit('update:modelValue',$event.src);picker=false" /></AdminDialog></div>
 <AdminPageLink v-else-if="schema.format==='url'" :model-value="modelValue||''" :label="title" :invalid="!!fieldError" @update:model-value="emit('update:modelValue',$event)" />
 <div v-else class="cms-field" :class="{'cms-field-long':typeof modelValue==='string'&&modelValue.length>80}"><label>{{ title }}<textarea v-if="!schema.format&&!schema.identity" :aria-describedby="hintId" :aria-invalid="!!fieldError" :readonly="schema.readOnly" :value="modelValue??''" rows="2" @input="emit('update:modelValue',($event.target as HTMLTextAreaElement).value)" /><input v-else :aria-describedby="hintId" :aria-invalid="!!fieldError" :readonly="schema.readOnly||schema.identity" :value="modelValue??''" @input="emit('update:modelValue',($event.target as HTMLInputElement).value)" /></label></div>
 <p v-if="fieldError||schema.help" :id="hintId" :class="fieldError?'cms-inline-error':'cms-field-help'" :role="fieldError?'alert':undefined">{{ fieldError||schema.help }}</p>
 </div>
</template>
